public function list()
  {
    $admin = User::where('id', '=', 1)->first();
    $adminSender = $admin
      ->devices()
      ->where('status', '=', 'ONLINE')
      ->value('sender');
    $user = auth()->user();
    $devices = $user->devices()->orderBy('status', 'desc')->paginate(50);
    $totalDevices = $user->devices()->count();
    $totalOnline = $user
      ->devices()
      ->where('status', '=', 'ONLINE')
      ->count();
    return view('/device-list', compact('adminSender', 'user', 'devices', 'totalDevices', 'totalOnline'));
  }
